/**
 * @param {number[]} flowers
 * @param {number} newFlowers
 * @param {number} target
 * @param {number} full
 * @param {number} partial
 * @return {number}
 */
var maximumBeauty = function(flowers, newFlowers, target, full, partial) {
    const n = flowers.length;
    const f = flowers.map(x => Math.min(x, target)).sort((a, b) => a - b);
    const prefix = new Array(n + 1).fill(0);
    for (let i = 0; i < n; i++) prefix[i + 1] = prefix[i] + f[i];
    let best = 0;
    // i = number of gardens left incomplete (first i), gardens i..n-1 made complete
    for (let i = n; i >= 0; i--) {
        const cost = (n - i) * target - (prefix[n] - prefix[i]);
        const remaining = newFlowers - cost;
        if (remaining < 0) break;
        const fullCount = n - i;
        if (i === 0) {
            best = Math.max(best, fullCount * full);
            continue;
        }
        // binary search max m in [f[0], target-1] s.t. cost to raise first i gardens to >= m <= remaining
        let lo = f[0], hi = target - 1;
        // cost(m): c = count of first i gardens with value < m; cost = c*m - prefix[c]
        const costM = (m) => {
            let l = 0, r = i;
            while (l < r) {
                const mid = (l + r) >> 1;
                if (f[mid] < m) l = mid + 1; else r = mid;
            }
            return l * m - prefix[l];
        };
        while (lo < hi) {
            const mid = Math.floor((lo + hi + 1) / 2);
            if (costM(mid) <= remaining) lo = mid; else hi = mid - 1;
        }
        best = Math.max(best, fullCount * full + lo * partial);
    }
    return best;
};
