 * @param {string} s
 * @return {string[]}
 */
var ambiguousCoordinates = function(s) {
    const digits = s.slice(1, -1);
    const n = digits.length;

    const gen = (str) => {
        const res = [];
        const len = str.length;
        if (len === 0) return res;
        // integer form
        if (len === 1 || str[0] !== '0') {
            res.push(str);
        }
        // decimal forms
        for (let i = 1; i < len; i++) {
            const left = str.slice(0, i);
            const right = str.slice(i);
            if (left.length > 1 && left[0] === '0') continue;
            if (right[right.length - 1] === '0') continue;
            res.push(left + '.' + right);
        }
        return res;
    };

    const result = [];
    for (let i = 1; i < n; i++) {
        const lefts = gen(digits.slice(0, i));
        const rights = gen(digits.slice(i));
        for (const a of lefts) {
            for (const b of rights) {
                result.push('(' + a + ', ' + b + ')');
            }
        }
    }
    return result;
};
