Sort the array, then for each value compute dp[x] = 1 + sum over divisor pairs (a, b) with a*b = x of dp[a]*dp[b], using a map. Use BigInt-safe multiplication via modular arithmetic (values < 1e9+7, product fits in 2^53? 1e9*1e9 = 1e18 > 2^53, so use BigInt or split multiplication).

```javascript
/**
 * @param {number[]} arr
 * @return {number}
 */
var numFactoredBinaryTrees = function(arr) {
    const MOD = 1000000007n;
    const sorted = [...arr].sort((a, b) => a - b);
    const dp = new Map();
    let total = 0n;
    for (let i = 0; i < sorted.length; i++) {
        const x = sorted[i];
        let ways = 1n;
        for (let j = 0; j < i; j++) {
            const a = sorted[j];
            if (a * a > x) break;
            if (x % a === 0) {
                const b = x / a;
                if (dp.has(b)) {
                    const wa = dp.get(a);
                    const wb = dp.get(b);
                    let prod = (wa * wb) % MOD;
                    if (a !== b) prod = (prod * 2n) % MOD;
                    ways = (ways + prod) % MOD;
                }
            }
        }
        dp.set(x, ways);
        total = (total + ways) % MOD;
    }
    return Number(total);
};
```

