            for (let step = k - 1; step <= k + 1; step++) {
                if (step <= 0) continue;
                const target = stones[i] + step;
                const j = idx.get(target);
                if (j !== undefined && j > i) {
                    dp[j].add(step);
                }
            }
        }
    }
    return dp[n - 1].size > 0;
