    for (let k = Math.min(m, n); k >= 2; k--) {
        for (let r = 0; r + k <= m; r++) {
            for (let c = 0; c + k <= n; c++) {
                if (check(r, c, k)) return k;
            }
        }
    }
    return 1;
};
