inference_trace:
Sliding window: for a window [l, r] of fruit positions, the cost is `min(|startPos - L| + (R - L), |startPos - R| + (R - L))`. Expand r, shrink l while cost exceeds k.

```javascript
/**
 * @param {number[][]} fruits
 * @param {number} startPos
 * @param {number} k
 * @return {number}
 */
var maxTotalFruits = function(fruits, startPos, k) {
    const n = fruits.length;
    let l = 0, sum = 0, best = 0;
    const cost = (L, R) => {
        const width = R - L;
        return width + Math.min(Math.abs(startPos - L), Math.abs(startPos - R));
    };
    for (let r = 0; r < n; r++) {
        sum += fruits[r][1];
        while (l <= r && cost(fruits[l][0], fruits[r][0]) > k) {
            sum -= fruits[l][1];
            l++;
        }
        if (sum > best) best = sum;
    }
    return best;
};
```

