```javascript
/**
 * @param {character[][]} seats
 * @return {number}
 */
var maxStudents = function(seats) {
    const m = seats.length;
    const n = seats[0].length;
    const full = 1 << n;

    // valid mask per row: seats good, no adjacent
    const rowAvail = new Array(m).fill(0);
    for (let i = 0; i < m; i++) {
        let mask = 0;
        for (let j = 0; j < n; j++) {
            if (seats[i][j].trim() === '.') mask |= (1 << j);
        }
        rowAvail[i] = mask;
    }

    const popcount = (x) => {
        let c = 0;
        while (x) { x &= x - 1; c++; }
        return c;
    };

    const validMasks = [];
    for (let mask = 0; mask < full; mask++) {
        if ((mask & (mask << 1)) === 0) validMasks.push(mask);
    }

    let prev = new Array(full).fill(-1);
    prev[0] = 0;

    for (let i = 0; i < m; i++) {
        const cur = new Array(full).fill(-1);
        for (const mask of validMasks) {
            if ((mask & ~rowAvail[i]) !== 0) continue;
            const cnt = popcount(mask);
            for (let pm = 0; pm < full; pm++) {
                if (prev[pm] < 0) continue;
                if ((mask & (pm << 1)) !== 0 || (mask & (pm >> 1)) !== 0) continue;
                const val = prev[pm] + cnt;
                if (val > cur[mask]) cur[mask] = val;
            }
        }
        prev = cur;
    }

    let ans = 0;
    for (let mask = 0; mask < full; mask++) {
        if (prev[mask] > ans) ans = prev[mask];
    }
    return ans;
};
