Standard approach: union-find on non-initial nodes, then for each component count how many distinct initial nodes touch it. For each initial node, sum sizes of components that it uniquely infects; pick the max (smallest index on ties).

```javascript
/**
 * @param {number[][]} graph
 * @param {number[]} initial
 * @return {number}
 */
var minMalwareSpread = function(graph, initial) {
    const n = graph.length;
    const isInit = new Array(n).fill(false);
    for (const x of initial) isInit[x] = true;

    const parent = new Array(n);
    const size = new Array(n).fill(1);
    for (let i = 0; i < n; i++) parent[i] = i;
    const find = (x) => {
        while (parent[x] !== x) {
            parent[x] = parent[parent[x]];
            x = parent[x];
        }
        return x;
    };
    const union = (a, b) => {
        a = find(a); b = find(b);
        if (a === b) return;
        if (size[a] < size[b]) [a, b] = [b, a];
        parent[b] = a;
        size[a] += size[b];
    };

    for (let i = 0; i < n; i++) {
        if (isInit[i]) continue;
        for (let j = i + 1; j < n; j++) {
            if (!isInit[j] && graph[i][j] === 1) union(i, j);
        }
    }

    // For each component root, which initial nodes touch it
    const touchCount = new Map(); // root -> count of distinct initial nodes
    const touchWho = new Map();   // root -> one initial node
    for (const x of initial) {
        const seen = new Set();
        for (let j = 0; j < n; j++) {
            if (!isInit[j] && graph[x][j] === 1) {
                const r = find(j);
                if (!seen.has(r)) {
                    seen.add(r);
                    touchCount.set(r, (touchCount.get(r) || 0) + 1);
                    touchWho.set(r, x);
                }
            }
        }
    }

    const saved = new Map();
    for (const [r, c] of touchCount) {
        if (c === 1) {
            const who = touchWho.get(r);
            saved.set(who, (saved.get(who) || 0) + size[r]);
        }
    }

    const sorted = [...initial].sort((a, b) => a - b);
    let best = sorted[0], bestVal = -1;
    for (const x of sorted) {
        const v = saved.get(x) || 0;
        if (v > bestVal) {
            bestVal = v;
            best = x;
        }
    }
    return best;
};
