Classic memoized recursion: f(n) = min(n%2 + 1 + f(n/2), n%3 + 1 + f(n/3)).

```javascript
/**
 * @param {number} n
 * @return {number}
 */
var minDays = function(n) {
    const memo = new Map();
    const f = (x) => {
        if (x <= 1) return x;
        if (memo.has(x)) return memo.get(x);
        const a = (x % 2) + 1 + f(Math.floor(x / 2));
        const b = (x % 3) + 1 + f(Math.floor(x / 3));
        const res = Math.min(a, b);
        memo.set(x, res);
        return res;
    };
    return f(n);
};
