```javascript
/**
 * @param {number[]} nums1
 * @param {number[]} nums2
 * @return {number}
 */
var numTriplets = function(nums1, nums2) {
    const buildFreq = (arr) => {
        const m = new Map();
        for (const x of arr) m.set(x, (m.get(x) || 0) + 1);
        return m;
    };

    const countType = (a, bFreq) => {
        // For each x in a, count pairs (j<k) in b with b[j]*b[k] == x*x
        let total = 0;
        const entries = [...bFreq.entries()];
        for (const x of a) {
            const sq = x * x;
            let cnt = 0;
            for (const [v, c] of entries) {
                if (sq % v !== 0) continue;
                const w = sq / v;
                if (w === v) {
                    cnt += c * (c - 1);
                } else {
                    const cw = bFreq.get(w);
                    if (cw) cnt += c * cw;
                }
            }
            total += cnt / 2;
        }
        return total;
    };

    const f1 = buildFreq(nums1);
    const f2 = buildFreq(nums2);
    return countType(nums1, f2) + countType(nums2, f1);
