Standard bitmask DP over subsets: dp[mask] = sum of chosen elements modulo target if reachable, filling subsets one at a time.

```javascript
/**
 * @param {number[]} nums
 * @param {number} k
 * @return {boolean}
 */
var canPartitionKSubsets = function(nums, k) {
    const n = nums.length;
    let total = 0;
    for (const x of nums) total += x;
    if (total % k !== 0) return false;
    const target = total / k;
    for (const x of nums) if (x > target) return false;

    const full = (1 << n) - 1;
    const dp = new Int32Array(1 << n).fill(-1);
    dp[0] = 0;
    for (let mask = 0; mask <= full; mask++) {
        if (dp[mask] < 0) continue;
        const cur = dp[mask];
        for (let i = 0; i < n; i++) {
            if (mask & (1 << i)) continue;
            if (cur + nums[i] > target) continue;
            const nxt = mask | (1 << i);
            if (dp[nxt] >= 0) continue;
            dp[nxt] = (cur + nums[i]) % target;
        }
    }
    return dp[full] === 0;
};
```

