Classic: choose n non-adjacent slices in a circular array maximizing sum. Solve linear version twice (excluding first or last element).

```javascript
/**
 * @param {number[]} slices
 * @return {number}
 */
var maxSizeSlices = function(slices) {
    const m = slices.length;
    const n = m / 3;
    const solve = (arr) => {
        const len = arr.length;
        // dp[i][j]: max sum using first i elements, choosing j non-adjacent
        const NEG = -Infinity;
        let dp = Array.from({ length: len + 1 }, () => new Array(n + 1).fill(NEG));
        for (let i = 0; i <= len; i++) dp[i][0] = 0;
        for (let i = 1; i <= len; i++) {
            for (let j = 1; j <= n; j++) {
                let skip = dp[i - 1][j];
                let take = (i >= 2 ? dp[i - 2][j - 1] : (j - 1 === 0 ? 0 : NEG)) + arr[i - 1];
                dp[i][j] = Math.max(skip, take);
            }
        }
        return dp[len][n];
    };
    if (m === 1) return slices[0];
    return Math.max(solve(slices.slice(1)), solve(slices.slice(0, m - 1)));
};
```

