Classic bitmask DP: `dp[mask]` = min stickers to cover the set of target positions in `mask`. For each reachable mask, pick the first uncovered letter and only try stickers containing it, applying each sticker greedily to uncovered positions.

```javascript
/**
 * @param {string[]} stickers
 * @param {string} target
 * @return {number}
 */
var minStickers = function(stickers, target) {
    const m = target.length;
    const full = (1 << m) - 1;
    const n = stickers.length;
    const counts = [];
    for (let i = 0; i < n; i++) {
        const c = new Array(26).fill(0);
        for (const ch of stickers[i]) c[ch.charCodeAt(0) - 97]++;
        counts.push(c);
    }
    const tcodes = [];
    for (let i = 0; i < m; i++) tcodes.push(target.charCodeAt(i) - 97);

    const dp = new Array(1 << m).fill(Infinity);
    dp[0] = 0;
    for (let mask = 0; mask < full; mask++) {
        if (dp[mask] === Infinity) continue;
        let first = -1;
        for (let i = 0; i < m; i++) {
            if (!(mask & (1 << i))) { first = i; break; }
        }
        const need = tcodes[first];
        for (let s = 0; s < n; s++) {
            if (counts[s][need] === 0) continue;
            const c = counts[s].slice();
            let nm = mask;
            for (let i = 0; i < m; i++) {
                if (nm & (1 << i)) continue;
                const ch = tcodes[i];
                if (c[ch] > 0) {
                    c[ch]--;
                    nm |= (1 << i);
                }
            }
            if (dp[mask] + 1 < dp[nm]) dp[nm] = dp[mask] + 1;
        }
    }
    return dp[full] === Infinity ? -1 : dp[full];
};
