    const stacks = Array.from({ length: 51 }, () => []); // each: array of [node, depth]
    const depth = new Array(n).fill(0);
    const parent = new Array(n).fill(-1);
    // iterative DFS with enter/exit
    const stack = [[0, false]];
    while (stack.length) {
        const [node, exiting] = stack.pop();
        const val = nums[node];
        if (exiting) {
            stacks[val].pop();
            continue;
        }
        // compute answer
